using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace RestApiMcpServer.Tools;

[McpServerToolType]
public class UserApiTools(HttpClient httpClient, ILogger<UserApiTools> logger)
{
    [McpServerTool, Description("Get a user by their numeric ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID to look up")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var user = await httpClient.GetFromJsonAsync<User>(
            $"/users/{userId}", cancellationToken);
        return $"Name: {user?.Name}, Email: {user?.Email}, Company: {user?.Company?.Name}";
    }

    [McpServerTool, Description("List all users from the REST API.")]
    public async Task<string> ListUsers(CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing all users");
        var users = await httpClient.GetFromJsonAsync<User[]>("/users", cancellationToken);
        return string.Join("\n", users?.Select(u => $"[{u.Id}] {u.Name} ({u.Email})") ?? []);
    }

    [McpServerTool, Description("Search for users whose name contains the given query string.")]
    public async Task<string> SearchUsers(
        [Description("Partial name to search for (case-insensitive)")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching users matching '{Query}'", query);
        var users = await httpClient.GetFromJsonAsync<User[]>("/users", cancellationToken);
        var matches = users?.Where(u =>
            u.Name?.Contains(query, StringComparison.OrdinalIgnoreCase) == true);
        return matches?.Any() == true
            ? string.Join("\n", matches.Select(u => $"[{u.Id}] {u.Name} ({u.Email})"))
            : "No users found matching that query.";
    }
}

