// CRITICAL: all logs go to stderr so stdout stays clean for MCP JSON-RPC protocol.
builder.Logging.AddConsole(o => o.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient for DI — the SDK injects it into tool constructors automatically.
builder.Services.AddHttpClient("RestApi", client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

// Wire up MCP: stdio transport + discover all [McpServerToolType] classes in the assembly.
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

