using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class PostsApiTools(IHttpClientFactory httpClientFactory, ILogger<PostsApiTools> logger)
{
    [McpServerTool, Description("Get a blog post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post to retrieve (1-100).")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var client = httpClientFactory.CreateClient("RestApi");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{postId}", cancellationToken);
        return $"Title: {post!.Title}\n\nBody: {post.Body}";
    }

    [McpServerTool, Description("Search posts by user ID. Returns all posts authored by that user.")]
    public async Task<string> GetPostsByUser(
        [Description("The user ID to filter posts by (1-10).")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching posts for user {UserId}", userId);
        var client = httpClientFactory.CreateClient("RestApi");
        var posts = await client.GetFromJsonAsync<Post[]>($"/posts?userId={userId}", cancellationToken);
        return string.Join("\n---\n", posts!.Select(p => $"[{p.Id}] {p.Title}"));
    }

    [McpServerTool, Description("Get all comments on a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to retrieve comments for.")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("RestApi");
        var comments = await client.GetFromJsonAsync<Comment[]>($"/posts/{postId}/comments", cancellationToken);
        return string.Join("\n---\n", comments!.Select(c => $"{c.Name} ({c.Email}):\n{c.Body}"));
    }
}

public record Post
{
    [JsonPropertyName("id")] public int Id { get; init; }
    [JsonPropertyName("userId")] public int UserId { get; init; }
    [JsonPropertyName("title")] public string Title { get; init; } = "";
    [JsonPropertyName("body")] public string Body { get; init; } = "";
}

public record Comment
{
    [JsonPropertyName("name")] public string Name { get; init; } = "";
    [JsonPropertyName("email")] public string Email { get; init; } = "";
    [JsonPropertyName("body")] public string Body { get; init; } = "";
}

